-- Resolve PrimaryRubricIds from SubSectionMaster when names match (read-only lookup).
UPDATE g
SET PrimaryRubricIdsJson = (
    SELECT CONCAT(N'[', STRING_AGG(CAST(s.SubSectionId AS NVARCHAR(20)), N','), N']')
    FROM OPENJSON(g.DoctorRubricsJson)
         WITH (subSectionName NVARCHAR(500) '$.subSectionName') j
    INNER JOIN dbo.SubSectionMaster s
        ON s.DeleteStatus = 0
       AND s.SubSectionName = j.subSectionName
)
FROM dbo.GoldCaseLibrary g
WHERE g.FollowUpOutcome = N'RegressionCase_NearZeroDiscovery'
  AND (g.PrimaryRubricIdsJson IS NULL OR g.PrimaryRubricIdsJson = N'[]');
GO
